import {
  Project,
  ProjectRepository,
  Task,
  TaskFilter,
  TaskRepository,
  User,
  UserRepository,
} from "../domain/model";

export class InMemoryUserRepository implements UserRepository {
  private readonly items = new Map<string, User>();

  save(user: User): void {
    this.items.set(user.id, user);
  }

  findById(id: string): User | undefined {
    return this.items.get(id);
  }
}

export class InMemoryProjectRepository implements ProjectRepository {
  private readonly items = new Map<string, Project>();

  save(project: Project): void {
    this.items.set(project.id, project);
  }

  findById(id: string): Project | undefined {
    return this.items.get(id);
  }
}

export class InMemoryTaskRepository implements TaskRepository {
  private readonly items = new Map<string, Task>();

  save(task: Task): void {
    this.items.set(task.id, task);
  }

  findById(id: string): Task | undefined {
    return this.items.get(id);
  }

  findByProject(projectId: string, filter: TaskFilter): Task[] {
    return [...this.items.values()].filter(
      (t) =>
        t.projectId === projectId &&
        (filter.status === undefined || t.status === filter.status) &&
        (filter.assigneeId === undefined || t.assigneeId === filter.assigneeId),
    );
  }
}

